# ============================================================
# Core functions
# ============================================================
def infer_image_bytes(image_bytes, confidence=0.5):
    """Send image bytes to the Roboflow model via REST API"""
    url = f"https://detect.roboflow.com/{MODEL_ID}"
    params = {"api_key": ROBOFLOW_API_KEY, "confidence": int(confidence * 100)}
    response = requests.post(url, params=params, files={"file": image_bytes})
    response.raise_for_status()
    return response.json()


def split_image_into_9(pil_image):
    img = np.array(pil_image.convert("RGB"))
    h, w = img.shape[:2]
    tile_w, tile_h = w // 3, h // 3
    tiles = []
    for row in range(3):
        for col in range(3):
            x1, y1 = col * tile_w, row * tile_h
            x2 = w if col == 2 else x1 + tile_w
            y2 = h if row == 2 else y1 + tile_h
            tiles.append(Image.fromarray(img[y1:y2, x1:x2]))
    return tiles


def pil_to_bytes(pil_image):
    buf = io.BytesIO()
    pil_image.save(buf, format="JPEG")
    buf.seek(0)
    return buf


def draw_boxes(pil_image, predictions):
    img = np.array(pil_image.convert("RGB"))
    for pred in predictions:
        x, y = int(pred["x"]), int(pred["y"])
        w, h = int(pred["width"]), int(pred["height"])
        x1, y1, x2, y2 = x - w // 2, y - h // 2, x + w // 2, y + h // 2
        is_infected = pred["class"].lower() == TARGET_CLASS.lower()
        color = (217, 86, 76) if is_infected else (63, 166, 107)
        cv2.rectangle(img, (x1, y1), (x2, y2), color, 2)
    return Image.fromarray(img)


def calculate_infection_rate(total_cells, infected_cells):
    if total_cells == 0:
        return 0.0, "no_data"
    percent = round((infected_cells / total_cells) * 100, 2)
    if percent == 0:
        level = "negative"
    elif percent <= 2:
        level = "mild"
    elif percent <= 5:
        level = "moderate"
    else:
        level = "severe"
    return percent, level


# ---- Risk profile scoring -----------------------------------
# Base score comes from the AI detection result (% infected cells).
# The dog-profile modifiers below are added on top, based on general
# risk factors reported in veterinary literature for ehrlichiosis
# (age extremes and pre-existing/immunosuppressive conditions are
# linked to more severe disease; certain breeds such as German
# Shepherds are reported as more prone to severe or chronic forms).
# This is a simple illustrative scoring model for screening only --
# not a validated clinical risk score.
GSD_KEYWORDS = ["german shepherd", "\u0e40\u0e22\u0e2d\u0e23\u0e21\u0e31\u0e19\u0e40\u0e0a\u0e35\u0e1e\u0e2d\u0e23\u0e4c\u0e14"]

def profile_risk_modifier(age_years, has_condition, breed):
    modifier = 0
    reasons = []
    if age_years is not None:
        if age_years < 1:
            modifier += 8
            reasons.append("Puppy (<1 year) -- immune system still developing")
        elif age_years >= 8:
            modifier += 8
            reasons.append("Senior dog (8+ years) -- weaker immune response")
    if has_condition:
        modifier += 12
        reasons.append("Pre-existing condition -- possible immunosuppression")
    if breed and any(k in breed.strip().lower() for k in GSD_KEYWORDS):
        modifier += 6
        reasons.append("Breed reported prone to more severe/chronic disease (German Shepherd)")
    return modifier, reasons


